<script>
(()=>{const layout=document.querySelector('.cart-layout');if(!layout)return;const csrf=document.querySelector('.cart-quantity-form input[name="_csrf"]')?.value||'',status=document.querySelector('.cart-async-status'),money=new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'}),rowsRoot=document.querySelector('.cart-products-list');function say(message,error=false){if(!error){status.textContent='' ;status.hidden=true;status.classList.remove('error');return}status.textContent=message;status.hidden=false;status.classList.add('error')}function updateSummary(cart){const subtotal=cart.subtotal_cents,threshold=Number(document.querySelector('[data-cart-free-shipping]')?.dataset.thresholdCents||4090),remaining=Math.max(0,threshold-subtotal),progress=Math.min(100,Math.round(subtotal/threshold*100)),itemsCount=cart.count;document.querySelector('[data-cart-subtotal] strong').textContent=money.format(subtotal/100);document.querySelector('[data-cart-count-label]').textContent=`(${itemsCount} ${itemsCount===1?'продукт':'продукта'})`;document.querySelector('[data-cart-total] strong:last-child').textContent=money.format(subtotal/100);document.querySelector('[data-cart-shipping]').lastElementChild.textContent=remaining===0?'Безплатна':'При поръчка';document.querySelector('[data-cart-summary-note]').textContent=(remaining===0?'Безплатната доставка се потвърждава при оформяне на поръчката.':'Доставката се уточнява при оформяне на поръчката.')+' Добавянето в количката не резервира наличност.';const free=document.querySelector('[data-cart-free-shipping]');free.classList.toggle('is-reached',remaining===0);free.querySelector('.cart-free-shipping-copy strong').textContent=remaining===0?'Достигнахте безплатна доставка':'Безплатна доставка';free.querySelector('.cart-free-shipping-copy span').textContent=remaining===0?'Покрихте прага за безплатна доставка.':`Добави още ${money.format(remaining)} и получи безплатна доставка!`;free.querySelector('.cart-shipping-progress span').style.width=progress+'%';free.querySelector('.cart-shipping-progress').setAttribute('aria-valuenow',String(progress));const badge=document.querySelector('.cart-badge');if(badge){badge.textContent=String(itemsCount);badge.closest('.cart-link')?.setAttribute('aria-label',`Количка, ${itemsCount} продукта`)}}async function mutate(row,url,method,body,trigger){if(row.dataset.pending==='1')return;row.dataset.pending='1';row.setAttribute('aria-busy','true');const spinnerTarget=trigger?.matches('input')?trigger.closest('.cart-quantity-control'):trigger;let spinner=null;if(spinnerTarget){spinnerTarget.classList.add('cart-action-spinner-host');spinner=document.createElement('span');spinner.className='cart-action-spinner';spinner.setAttribute('aria-hidden','true');spinnerTarget.append(spinner)}row.querySelectorAll('button,input').forEach(control=>control.disabled=true);try{const response=await fetch(url,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-Token':csrf},...(body?{body:JSON.stringify(body)}:{})}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Промяната не беше запазена.');const cart=payload.data.cart;if(method==='DELETE')row.remove();else{const item=cart.items.find(candidate=>candidate.item_key===row.dataset.itemKey);if(item){const input=row.querySelector('input[name="quantity"]');input.value=String(item.quantity);input.dataset.committedQuantity=String(item.quantity);row.querySelector('[data-unit-price-cents]').lastChild.textContent=money.format(item.unit_price_current_cents/100);row.querySelector('[data-line-total-cents]').lastChild.textContent=money.format(item.line_total_cents/100)}}for(const item of cart.items){const current=rowsRoot.querySelector(`[data-item-key="${CSS.escape(item.item_key)}"]`);if(current&&current.dataset.itemKey!==row.dataset.itemKey){const input=current.querySelector('input[name="quantity"]');input.value=String(item.quantity);input.dataset.committedQuantity=String(item.quantity);current.querySelector('[data-line-total-cents]').lastChild.textContent=money.format(item.line_total_cents/100)}}updateSummary(cart);window.dispatchEvent(new CustomEvent('cart:updated',{detail:cart}));say(payload.data.message);if(cart.items.length===0){const template=document.querySelector('#cart-empty-template');layout.replaceWith(template.content.cloneNode(true));status.hidden=true}}catch(error){if(method==='PATCH'){const input=row.querySelector('input[name="quantity"]');input.value=input.dataset.committedQuantity||input.defaultValue}say(error instanceof Error?error.message:'Възникна грешка. Опитайте отново.',true)}finally{if(spinner){spinner.classList.add('is-leaving');window.setTimeout(()=>{spinner.remove();spinnerTarget.classList.remove('cart-action-spinner-host')},140)}if(row.isConnected){delete row.dataset.pending;row.removeAttribute('aria-busy');row.querySelectorAll('button,input').forEach(control=>control.disabled=false)}}}document.querySelectorAll('[data-quantity-stepper]').forEach(form=>{const input=form.querySelector('input[name="quantity"]'),row=form.closest('.cart-row'),url='/cart/items/'+encodeURIComponent(row.dataset.itemKey);input.dataset.committedQuantity=input.value;function save(trigger=form.querySelector('.cart-quantity-control')){const value=Math.max(1,Math.min(999,Number(input.value)||1));input.value=String(value);if(value!==Number(input.dataset.committedQuantity))mutate(row,url,'PATCH',{quantity:value},trigger)}form.addEventListener('submit',event=>event.preventDefault());form.querySelectorAll('[data-quantity-delta]').forEach(button=>button.addEventListener('click',()=>{const current=Number(input.value)||1;if(Number(button.dataset.quantityDelta)<0&&current<=1){mutate(row,'/cart/items/'+encodeURIComponent(row.dataset.itemKey),'DELETE',undefined,button);return}input.value=String(Math.max(1,Math.min(999,current+Number(button.dataset.quantityDelta))));save(button)}));input.addEventListener('change',()=>save(form.querySelector('.cart-quantity-control')))});document.querySelectorAll('.cart-remove-form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();mutate(form.closest('.cart-row'),'/cart/items/'+encodeURIComponent(form.closest('.cart-row').dataset.itemKey),'DELETE',undefined,form.querySelector('button'))}))})();
</script>
<script>(()=>{const format=new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'});window.addEventListener('cart:updated',event=>{const cart=event.detail;if(!cart)return;const discount=Number(cart.discount_cents||0),subtotal=Number(cart.subtotal_cents||0),total=Math.max(0,subtotal-discount),row=document.querySelector('[data-cart-discount]');if(row){row.querySelector('span').textContent='Отстъпка'+(cart.discount_code?' ('+cart.discount_code+')':'');row.querySelector('strong').textContent='− '+format.format(discount/100)}const totalValue=document.querySelector('[data-cart-total] strong:last-child');if(totalValue)totalValue.textContent=format.format(total/100);const note=document.querySelector('[data-cart-summary-note]');if(note)note.textContent=(discount>0?'Отстъпката е приложена към продуктите. ':'')+'Добавянето в количката не резервира наличност.';const shipping=document.querySelector('[data-cart-free-shipping]');if(shipping){const threshold=Number(shipping.dataset.thresholdCents||0),remaining=Math.max(0,threshold-total),progress=threshold>0?Math.min(100,Math.round(total/threshold*100)):100;shipping.classList.toggle('is-reached',remaining===0);shipping.querySelector('.cart-free-shipping-copy strong').textContent=remaining===0?'Достигнахте безплатна доставка':'Безплатна доставка';shipping.querySelector('.cart-free-shipping-copy span').textContent=remaining===0?'Покрихте прага за безплатна доставка.':`Добави още ${format.format(remaining/100)} и получи безплатна доставка!`;shipping.querySelector('.cart-shipping-progress span').style.width=progress+'%';shipping.querySelector('.cart-shipping-progress').setAttribute('aria-valuenow',String(progress))}const applied=document.querySelector('.cart-promo-applied');if(applied&&cart.discount_code)applied.textContent=`Кодът ${cart.discount_code} е приложен. Спестявате ${format.format(discount/100)}.`})})();</script>
